  if (
    entry === null || typeof entry !== "object" ||
    !("hash" in entry) || typeof entry.hash !== "string" ||
    !/^[0-9a-f]{64}$/.test(entry.hash) ||
    !("created_at" in entry) || typeof entry.created_at !== "string" ||
    !/^(0|[1-9][0-9]*)$/.test(entry.created_at)
  )
    throw new Error("The actual migration ledger row is malformed.");
  return { hash: entry.hash, created_at: entry.created_at };
}),
